                // hidden background scrapes. Calling Focus() there pulls keyboard focus into
                // the tool window, which makes VS activate the Claude Usage tab unexpectedly.
                WebView.ZoomFactorChanged += (s, e) =>
                {
                    if (SuppressFocus) return;
