console.log(JSON.stringify(r.result?.result?.value ?? r, null, 1));
const s = await send('Page.captureScreenshot', {format:'png'});
if (s.result) (await import('fs')).writeFileSync(process.argv[5] || 'C:/Temp/cc-tools/shot.png', Buffer.from(s.result.data,'base64'));
